        ctx.next()?;
        ctx.lines_as(
            "Basshu",
            args![
                "1 Mirror Shield, and",
                "20,000 Zeny, and I'll improve your Arm Guard into an Improved Arm Guard."
            ],
        )?;
        ctx.next()?;
        ctx.lines_as("Basshu", args!["How about it? Would you like that?"])?;
